        ],
    );
    let vb_job = Job::new(
        "The Veteran Broker, LLC",
        "Software Developer",
        "Jan 2022 - Sep 2022",
        vec![
            "Integrated a sign-up form with DocuSign, saving the CEO 10-15 hours per month",
            "Integrated DocuSign for client portal which notified users to complete new \
            beneficiary designation form and saved the CEO 15 hours per month",
        ],
    );
    let mc_job = Job::new(
        "Mid-City Supply Co.",
