use gpui::*;

#[derive(Clone, IntoElement)]
pub struct Contact {
    pub email: SharedString,
    pub github: SharedString,
    pub linkedin: SharedString,
}

impl Contact {
    pub fn new(
        email: impl Into<SharedString>,
        github: impl Into<SharedString>,
        linkedin: impl Into<SharedString>,
    ) -> Self {
        Self {
            email: email.into(),
            github: github.into(),
            linkedin: linkedin.into(),
        }
    }
}

impl RenderOnce for Contact {
    fn render(self, _: &mut WindowContext) -> impl IntoElement {
        fn link<E: Styled + InteractiveElement>(url: String, el: E) -> E {
            el.on_mouse_down(MouseButton::Left, move |_, cx| {
                cx.open_url(&url);
            })
            .px_3()
            .py_1()
            .rounded_md()
            .border_1()
            .border_color(rgb(0xbbbbbb))
            .hover(|style| {
                style
                    .cursor(CursorStyle::PointingHand)
                    .bg(hsla(0.0, 0.0, 1.0, 0.07))
                    .border_color(rgb(0xeeeeee))
            })
        }

        div()
            .flex()
            .flex_col()
            .gap_2()
            .child(link(
                format!("mailto:{}", self.email),
                div().child(self.email),
            ))
            .child(link(
                format!("https://{}", self.linkedin),
                div().child(self.linkedin),
            ))
            .child(link(
                format!("https://{}", self.github),
                div().child(self.github),
            ))
    }
}
