use gpui::{
    div, list, prelude::*, px, FontWeight, ListAlignment, ListState, SharedString, WindowContext,
};

#[derive(Clone, IntoElement)]
pub struct Job {
    company: SharedString,
    title: SharedString,
    dates: SharedString,
    bullets: Vec<SharedString>,
    list_state: ListState,
}

impl Job {
    pub fn new(
        company: impl Into<SharedString>,
        title: impl Into<SharedString>,
        dates: impl Into<SharedString>,
        bullets: Vec<impl Into<SharedString>>,
    ) -> Self {
        let len = bullets.len();
        let this = Self {
            company: company.into(),
            title: title.into(),
            dates: dates.into(),
            bullets: bullets.into_iter().map(Into::into).collect(),
            list_state: ListState::new(len, ListAlignment::Top, px(1000.), move |ix, cx| {
                div().id(ix).into_any()
            }),
        };

        this
    }
}

impl RenderOnce for Job {
    fn render(self, _: &mut WindowContext) -> impl IntoElement {
        div()
            .m_4()
            .child(div().mt_2().text_xl().child(self.company.clone()))
            .child(
                div()
                    .text_lg()
                    .font_weight(FontWeight::BOLD)
                    .child(self.title.clone()),
            )
            .child(div().text_sm().child(self.dates.clone()))
            .child(list(self.list_state))
    }
}
